fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // Helper: Check if n is a power of two
    fn is_power_of_two(mut n: i32) -> bool {
        n > 0 && (n & (n - 1)) == 0
    }

    // Helper: Determine if p is "limited-prime" based on problem rules
    // p ≤ 1 -> not prime
    // p = 2 -> prime
    // p even and > 2 -> not prime
    // p odd and > 2 -> prime
    fn is_limited_prime(p: i32) -> bool {
        if p <= 1 {
            false
        } else if p == 2 {
            true
        } else if p % 2 == 0 {
            false
        } else {
            true
        }
    }

    let t = input[0] as usize;
    let games = &input[1..=t];

    let mut results = Vec::with_capacity(t);

    for &n_i8 in games {
        let n = n_i8 as i32;

        let winner = if n == 1 {
            "FastestFinger"
        } else if n == 2 {
            "Ashishgup"
        } else if is_power_of_two(n) {
            // n > 2 and power of two
            "FastestFinger"
        } else if n % 4 != 2 {
            // includes odd numbers and multiples of 4
            "Ashishgup"
        } else {
            // n % 4 == 2
            // p = n / 2
            let p = n / 2;
            if is_limited_prime(p) {
                "FastestFinger"
            } else {
                "Ashishgup"
            }
        };

        results.push(winner);
    }

    results
}